/* Absolute export-relative paths; reject reparse points at every component. */
#include "LLTREE.H"
static int win_tree_full(char*out,const char*base,const char*rel){char pathrel[64],part[13];unsigned n,i=0,j;DWORD a;if(!reljoin(pathrel,base,rel))return 0;textcopy(out,localbase);a=GetFileAttributesA(out);if(a==0xffffffffUL||!(a&16)||(a&0x400))return 0;while(pathrel[i]){j=0;while(pathrel[i]&&pathrel[i]!='\\')part[j++]=pathrel[i++];part[j]=0;n=slen(out);if(n+j+2>=239)return 0;out[n++]='\\';textcopy(out+n,part);a=GetFileAttributesA(out);if(a&0x400&&a!=0xffffffffUL)return 0;if(pathrel[i]){if(a==0xffffffffUL||!(a&16))return 0;i++;}}return 1;}
static int win_tree_parent(char*out,char*leaf,const char*base,const char*rel){char p[64];unsigned i=slen(rel);while(i&&rel[i-1]!='\\')i--;textcopy(leaf,rel+i);if(!valid(leaf))return 0;textcopy(p,rel);if(i)p[i-1]=0;else p[0]=0;return win_tree_full(out,base,p);}
static HANDLE tree_find=INVALID_HANDLE_VALUE;static WIN32_FIND_DATAA tree_found;static char tree_findpath[260];static u16 tree_findnext;
static void tree_findclose(void){if(tree_find!=INVALID_HANDLE_VALUE)FindClose(tree_find);tree_find=INVALID_HANDLE_VALUE;}
static int win_tree_scan(const char*base,const char*rel,u16 ordinal,u8*entry){char p[260];unsigned at;DWORD error;int rc;if(!win_tree_full(p,base,rel))return -1;if(tree_find!=INVALID_HANDLE_VALUE&&ordinal&&ordinal==tree_findnext&&same(p,tree_findpath)){at=ordinal;rc=FindNextFileA(tree_find,&tree_found);}else{tree_findclose();textcopy(tree_findpath,p);textcopy(p+slen(p),"\\*.*");at=0;tree_find=FindFirstFileA(p,&tree_found);rc=tree_find!=INVALID_HANDLE_VALUE;}if(!rc&&tree_find==INVALID_HANDLE_VALUE){error=GetLastError();return error==ERROR_FILE_NOT_FOUND||error==ERROR_NO_MORE_FILES?0:-1;}while(rc){if(!navname(tree_found.cFileName)){if(at++==ordinal){if(ordinal>=4096){tree_findclose();return -1;}if(!valid(tree_found.cFileName)||(tree_found.dwFileAttributes&0x400)){logline("Folder item skipped: unsupported name or reparse point");logline(tree_found.cFileName);tree_findnext=ordinal+1;return -2;}zero(entry,22);textcopy((char*)entry,tree_found.cFileName);set32(entry+13,tree_found.nFileSizeLow);entry[17]=(u8)tree_found.dwFileAttributes;FileTimeToDosDateTime(&tree_found.ftLastWriteTime,(WORD*)(entry+18),(WORD*)(entry+20));tree_findnext=ordinal+1;return 1;}}rc=FindNextFileA(tree_find,&tree_found);}error=GetLastError();tree_findclose();return error==ERROR_NO_MORE_FILES?0:-1;}
static int win_tree_mkdir(const char*base,const char*rel){char p[260];DWORD a;if(!rel[0]||!win_tree_full(p,base,rel))return INVALID;a=GetFileAttributesA(p);if(a!=0xffffffffUL)return a&16?OK:EXISTS;return CreateDirectoryA(p,0)?OK:IOERR;}
static int win_tree_server(const u8*data,unsigned n){char rel[64],full[260],leaf[13],saved[260];u8 e[22];unsigned op,ordinal;int k,ok=1,st;if(n<4||n>67||data[n-1]||slen((char*)data+3)!=n-4||!relvalid((char*)data+3))return statusout(RESULT,INVALID);op=data[0];ordinal=get16(data+1);textcopy(rel,(char*)data+3);
 if(op==TC_SCAN){k=win_tree_scan("",rel,ordinal,e);return k>0?frameout(ENTRY,e,22):statusout(RESULT,k==-2?TREE_SKIP:(k<0?IOERR:OK));}
 if(op==TC_MKDIR)return statusout(RESULT,(u16)win_tree_mkdir("",rel));
 if(op!=TC_GET&&op!=TC_PUT)return statusout(RESULT,INVALID);if(!win_tree_parent(full,leaf,"",rel))return statusout(RESULT,INVALID);textcopy(saved,basedir);textcopy(basedir,full);
 if(op==TC_GET){st=sendfile(leaf,leaf,0,0);if(st<0)ok=0;else if(st==MISSING||st==IOERR||st==INVALID)ok=statusout(RESULT,(u16)st);}
 else if(!statusout(RESULT,OK))ok=0;else{k=framein();if(k!=PUT||plen!=21||payload[12]||!same((char*)payload,leaf))ok=0;else ok=recvfile(0)||!transport_failed;}
 textcopy(basedir,saved);return ok;}
static int tree_request(unsigned op,const char*rel,u16 index){u8 b[67];if(!relvalid(rel))return 0;b[0]=(u8)op;set16(b+1,index);textcopy((char*)b+3,rel);return frameout(LL_TREE,b,slen(rel)+4);}
